const binaryKeys = Object.keys($binary);
if (binaryKeys.length === 0) {
  throw new Error('No binary data received');
}
const key = binaryKeys[0];
const binaryInfo = $binary[key];

const headers = $json.headers || {};
const tenantId = headers['x-tenant-id'] || '00000000-0000-0000-0000-000000000001';
const documentId = headers['x-document-id'] || '';
const knowledgeBaseId = headers['x-knowledge-base-id'] || '';

// Pass through binary data as-is (keep id for Stream path)
// The patched getItemBinaryData now uses metadata.mimeType from storage
return [{
  json: {
    tenantId,
    documentId,
    knowledgeBaseId,
    binaryKey: key
  },
  binary: {
    [key]: binaryInfo
  }
}];

const metadata = $('Fix MIME Type').item.json;
const driveResult = $('Google Drive').item.json;

return [{
  json: {
    success: true,
    documentId: metadata.documentId,
    tenantId: metadata.tenantId,
    filename: driveResult.name || '',
    fileUrl: 'https://drive.google.com/file/d/' + (driveResult.id || '') + '/view',
    storageProvider: 'gdrive',
    gdriveFileId: driveResult.id || '',
    mimeType: driveResult.mimeType || '',
    timestamp: new Date().toISOString()
  }
}];
